-- Generated by model/lib/sql/generate.mjs. L1's load of Volume Growth IN from cells/Volume Growth IN.csv in the folder of input cells, into its empty table.
-- Two rows for one cell add up.
-- @csv cells/Volume Growth IN.csv
INSERT INTO "Volume Growth IN" SELECT coalesce(k0."Brand", fpabench_error('cells name a member Brand does not have: ' || c."Brand")), coalesce(k1."Channel", fpabench_error('cells name a member Channel does not have: ' || c."Channel")), coalesce(k2."Versions", fpabench_error('cells name a member Versions does not have: ' || c."Versions")), coalesce(k3."Years", fpabench_error('cells name a member Years does not have: ' || c."Years")), sum(c.value::DOUBLE PRECISION)
FROM csv c LEFT JOIN "dim Brand" k0 ON k0.name = c."Brand" LEFT JOIN "dim Channel" k1 ON k1.name = c."Channel" LEFT JOIN "dim Versions" k2 ON k2.name = c."Versions" LEFT JOIN "dim Years" k3 ON k3.name = c."Years"
GROUP BY 1, 2, 3, 4;
ANALYZE "Volume Growth IN";
